const body = $input.item.json.body || {};
const reportId = body.reportId;
const filename = body.filename || body.originalFilename;

if (!reportId || !filename) {
  throw new Error('Missing reportId or filename');
}

// Force container path for n8n
const containerPath = `/app/uploads/${filename}`;

return [{ json: { reportId, filepath: containerPath, filename, originalFilename: body.originalFilename, timestamp: new Date().toISOString() } }];

const { execSync } = require('child_process');
const inputData = $('Validate Input Data').first().json;
const filepath = inputData.filepath;
const reportId = inputData.reportId;

// Construct command
const cmd = `python3 /home/node/scripts/profile_data.py "${filepath}" "${reportId}"`;

try {
  const stdout = execSync(cmd, { encoding: 'utf8' });
  let result = {};
  try { result = JSON.parse(stdout); } catch(e) { result = { raw: stdout }; }
  return [{ json: { profiling_complete: true, profiling_result: result, processed_file: filepath, reportId } }];
} catch (error) {
  throw new Error(`Profile script failed: ${error.message}`);
}

