const root = $input.item.json;
const candidates = root.candidates || (root.response && root.response.candidates);
const text = candidates ? candidates[0].content.parts[0].text : 'No insights generated.';
const reportId = $('Validate Input Data').first().json.reportId;
return [{ json: { insights: text, reportId } }];
